    #Node Math
    def math(
        self,
        value: Float = None,
        addend: Float = None,
        *,
        multiplier: Float = None,
        exponent: Float = None,
        base: Float = None,
        threshold: Float = None,
        max: Float = None,
        increment: Float = None,
        scale: Float = None,
        epsilon: Float = None,
        distance: Float = None,
        min: Float = None,
        use_clamp: bool = False,
        operation: T_OPERATION_5 = 'ADD'):
        """Node Math.
        
        Jump: False
        
        Parameters
        ----------
        operation : {'ADD', 'SUBTRACT', 'MULTIPLY', 'DIVIDE', 'MULTIPLY_ADD', 'POWER', 'LOGARITHM', 'SQRT', 'INVERSE_SQRT', 'ABSOLUTE', 'EXPONENT', 'MINIMUM', 'MAXIMUM', 'LESS_THAN', 'GREATER_THAN', 'SIGN', 'COMPARE', 'SMOOTH_MIN', 'SMOOTH_MAX', 'ROUND', 'FLOOR', 'CEIL', 'TRUNC', 'FRACT', 'MODULO', 'FLOORED_MODULO', 'WRAP', 'SNAP', 'PINGPONG', 'SINE', 'COSINE', 'TANGENT', 'ARCSINE', 'ARCCOSINE', 'ARCTANGENT', 'ARCTAN2', 'SINH', 'COSH', 'TANH', 'RADIANS', 'DEGREES'}, optional
            Node parameter 'operation' (default: 'ADD')
        use_clamp : VALUE, optional
            Node parameter 'use_clamp' (default: False)
        value : Float, optional
            Alias of socket identifier: 'Value_001' (default: None)
        multiplier : Float, optional
            Alias of socket identifier: 'Value_001' (default: None)
        exponent : Float, optional
            Alias of socket identifier: 'Value_001' (default: None)
        base : Float, optional
            Alias of socket identifier: 'Value_001' (default: None)
        threshold : Float, optional
            Alias of socket identifier: 'Value_001' (default: None)
        max : Float, optional
            Alias of socket identifier: 'Value_001' (default: None)
        increment : Float, optional
            Alias of socket identifier: 'Value_001' (default: None)
        scale : Float, optional
            Alias of socket identifier: 'Value_001' (default: None)
        addend : Float, optional
            Alias of socket identifier: 'Value_002' (default: None)
        epsilon : Float, optional
            Alias of socket identifier: 'Value_002' (default: None)
        distance : Float, optional
            Alias of socket identifier: 'Value_002' (default: None)
        min : Float, optional
            Alias of socket identifier: 'Value_002' (default: None)
        

        Returns
        -------
        Socket
            Default output socket.
        """
        node = Node(
            'Math',
            named_sockets={'ID_Value': self, 'ID_Value_001': next((v for v in (value, multiplier, exponent, base, threshold, max, increment, scale) if v is not None), None), 'ID_Value_002': next((v for v in (addend, epsilon, distance, min) if v is not None), None)},
            operation=operation,
            use_clamp=use_clamp)
        
        return node._out

